package starlight

import (
	"strings"

	"github.com/alternayte/gx"
	"github.com/alternayte/gx/registry/docs"
)

// icon renders one built-in icon of the docs kit at the size of the text.
func icon(name docs.IconName, class string) gx.Node {
	return gx.Icon(string(docs.IconBody(name)), gx.IconProps{Class: gx.Cx("sl-icon", class)})
}

// Active reports whether href is the current page.
func Active(path string, href string) bool {
	return href != "" && path == href
}

// ActiveItem reports whether item or one of its descendants is the current
// page.
func ActiveItem(path string, item NavItem) bool {
	if Active(path, string(item.Href)) {
		return true
	}
	for _, child := range item.Items {
		if ActiveItem(path, child) {
			return true
		}
	}
	return false
}

// GroupOpen reports whether a sidebar group starts open: it is not
// collapsed, or it holds the current page.
func GroupOpen(path string, collapsed bool, items []NavItem) bool {
	if !collapsed {
		return true
	}
	for _, item := range items {
		if ActiveItem(path, item) {
			return true
		}
	}
	return false
}

// TocDepth returns the heading depth limit of the page.
func (p Page) TocDepth() int {
	if p.Depth <= 0 {
		return 3
	}
	return p.Depth
}

// ShownTOC returns the headings that the table of contents shows. A splash
// page has none.
func (p Page) ShownTOC() []Heading {
	if p.Splash {
		return nil
	}
	depth := p.TocDepth()
	var out []Heading
	for _, h := range p.TOC {
		if h.Level >= 2 && h.Level <= depth && h.Text != "" {
			out = append(out, h)
		}
	}
	return out
}

// RootClass returns the classes of the html element. The theme sets the
// widths of the layout from them.
func RootClass(p Page) string {
	if p.Splash {
		return ""
	}
	// A page with a sidebar always has the entry "Overview" in its table
	// of contents.
	return "sl-has-sidebar sl-has-toc"
}

// EditURL returns the edit link of the page. The page path maps to its
// Markdown file: "/start/" to "start.md".
func (c Config) EditURL(p Page) string {
	if c.EditBase == "" || p.Path == "" {
		return ""
	}
	base := c.EditBase
	if base[len(base)-1] != '/' {
		base += "/"
	}
	path := strings.TrimPrefix(p.Path, "/")
	path = strings.TrimSuffix(path, "/")
	if path == "" {
		path = "index"
	}
	return base + path + ".md"
}

// Package starlight is the starlight-shell registry block: the page
// structure of the default Starlight theme. It has a fixed header, a
// sidebar, a table of contents, a hero, page links and a search dialog.
// The `starlight` theme styles it; the `docs` kit holds its icons.
package starlight

import (
	"github.com/alternayte/gx"
	"github.com/alternayte/gx/registry/docs"
)

// Nav is the sidebar model.
type Nav struct {
	Groups []NavGroup
}

// NavGroup is one top-level sidebar section. A group with Collapsed starts
// closed, unless it holds the current page.
type NavGroup struct {
	Label     string
	Badge     string
	Collapsed bool
	Items     []NavItem
}

// NavItem is one sidebar link. An item with Items is a nested group; a
// nested group with Collapsed starts closed, unless it holds the current
// page.
type NavItem struct {
	Label     string
	Href      gx.URL
	Badge     string
	Collapsed bool
	Items     []NavItem
}

// Link is one social link of the header. Icon is the name of a built-in
// icon of the docs kit, for example "github".
type Link struct {
	Label string
	Href  gx.URL
	Icon  docs.IconName
}

// Version is one version of the docs: its label and the address of its
// site.
type Version struct {
	Label string
	Href  gx.URL
}

// Config is the site-wide shell data.
type Config struct {
	Title string
	// Version is the label of the version that this site shows. The header
	// shows it after the title. Empty hides it.
	Version string
	// Versions lists the versions of the docs. With two or more, the
	// header shows a select in place of the label, and a choice opens the
	// site of that version.
	Versions []Version
	Links    []Link
	// EditBase is the repository edit URL up to the file path, for example
	// https://github.com/acme/site/edit/main/content/docs/. Empty hides
	// the edit link.
	EditBase string
}

// Page is the shell data of one page.
type Page struct {
	Title string
	// Path is the site path of the page, for example /start/.
	Path string
	// Splash is true for a page with no sidebar and no table of contents,
	// such as a home page.
	Splash bool
	// Updated is the date of the last change. Empty hides it.
	Updated string
	// Prev and Next are the previous and next sidebar items.
	Prev *NavItem
	Next *NavItem
	// TOC holds the page headings, in document order.
	TOC []Heading
	// Depth limits the table of contents to headings at or below this
	// level. Zero means 3.
	Depth int
}

// Heading is one table-of-contents entry.
type Heading struct {
	Level int
	Text  string
	ID    string
}
